<script setup lang="ts">
import{onMounted,ref}from'vue';import Button from'primevue/button';import{addAdminGallery,deleteAdminGallery,deleteMedia,getAdminGallery,uploadMedia,type AdminGalleryItem}from'@/api/admin'
import DeleteButton from '@/components/admin/DeleteButton.vue'
const props=defineProps<{token:string}>();const emit=defineEmits<{changed:[]}>();const items=ref<AdminGalleryItem[]>([]);const input=ref<HTMLInputElement|null>(null);const loading=ref(false);const error=ref('')
async function load(){loading.value=true;try{items.value=await getAdminGallery(props.token)}catch(e){error.value=e instanceof Error?e.message:'Не удалось загрузить галерею'}finally{loading.value=false}}
async function upload(event:Event){const files=Array.from((event.target as HTMLInputElement).files??[]);if(!files.length)return;loading.value=true;error.value='';for(const file of files){let mediaId:number|null=null;try{const media=await uploadMedia(props.token,file,'Фото галереи');mediaId=media.id;await addAdminGallery(props.token,media.id,file.name);mediaId=null}catch(e){if(mediaId)await deleteMedia(props.token,mediaId).catch(()=>{});error.value=e instanceof Error?e.message:'Не удалось загрузить фотографию';break}}if(input.value)input.value.value='';await load();emit('changed')}
async function remove(item:AdminGalleryItem){loading.value=true;try{await deleteAdminGallery(props.token,item.id);await load();emit('changed')}catch(e){error.value=e instanceof Error?e.message:'Не удалось удалить фотографию'}finally{loading.value=false}}
onMounted(load)
</script>
<template><section class="gallery"><div class="heading"><div><p class="eyebrow">Фотографии центра</p><h2>Галерея</h2><p>Загружайте фотографии отдельно от занятий, новостей и сотрудников.</p></div><Button label="Загрузить фотографии" :loading="loading" @click="input?.click()"/></div><input ref="input" hidden type="file" accept="image/*" multiple @change="upload"/><p v-if="error" class="form-error">{{error}}</p><div v-if="items.length" class="grid"><article v-for="item in items" :key="item.id"><img :src="item.media.url" :alt="item.title||item.media.alt"/><DeleteButton @confirm="remove(item)"/></article></div><p v-else-if="!loading" class="empty">В галерее пока нет фотографий.</p></section></template>
<style scoped>.gallery{display:grid;gap:1.25rem}.heading{display:flex;justify-content:space-between;align-items:flex-start;gap:1rem}.heading h2{margin:0}.heading p:not(.eyebrow){margin:.35rem 0;color:#647067}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:1rem}.grid article{display:grid;gap:.4rem;padding:.6rem;border:1px solid #e6e2d9;border-radius:12px}.grid img{width:100%;height:160px;object-fit:cover;border-radius:8px}.empty{padding:1rem;background:#f3f5f1;border-radius:10px;color:#647067}@media(max-width:650px){.heading{flex-direction:column}}</style>
